def countMsts(n, edges):
    MOD = 10 ** 9 + 7
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def det(mat):
        k = len(mat)
        res = 1
        for c in range(k):
            piv = -1
            for r in range(c, k):
                if mat[r][c] % MOD:
                    piv = r
                    break
            if piv < 0:
                return 0
            if piv != c:
                mat[piv], mat[c] = mat[c], mat[piv]
                res = -res
            res = res * mat[c][c] % MOD
            inv = pow(mat[c][c], MOD - 2, MOD)
            for r in range(c + 1, k):
                f = mat[r][c] * inv % MOD
                if f:
                    for j in range(c, k):
                        mat[r][j] = (mat[r][j] - f * mat[c][j]) % MOD
        return res % MOD

    es = sorted(edges, key=lambda e: e[2])
    ans = 1
    i = 0
    m = len(es)
    while i < m:
        j = i
        while j < m and es[j][2] == es[i][2]:
            j += 1
        group = []
        for k in range(i, j):
            ra, rb = find(es[k][0]), find(es[k][1])
            if ra != rb:
                group.append((ra, rb))
        # connected parts of the contracted multigraph
        local = {}
        for ra, rb in group:
            local.setdefault(ra, ra)
            local.setdefault(rb, rb)

        def lfind(x):
            while local[x] != x:
                local[x] = local[local[x]]
                x = local[x]
            return x

        for ra, rb in group:
            local[lfind(ra)] = lfind(rb)
        parts = {}
        for node in local:
            parts.setdefault(lfind(node), []).append(node)
        for nodes in parts.values():
            idx = {v: t for t, v in enumerate(nodes)}
            s = len(nodes)
            lap = [[0] * s for _ in range(s)]
            for ra, rb in group:
                if ra in idx and rb in idx:
                    x, y = idx[ra], idx[rb]
                    lap[x][x] += 1
                    lap[y][y] += 1
                    lap[x][y] -= 1
                    lap[y][x] -= 1
            minor = [[v % MOD for v in row[:-1]] for row in lap[:-1]]
            ans = ans * det(minor) % MOD
        for ra, rb in group:
            a, b = find(ra), find(rb)
            if a != b:
                parent[a] = b
        i = j
    return ans % MOD
